import math
import sys

def main():
    import sys
    import math

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    t = readints()[0]
    results = []

    for _ in range(t):
        n, k = readints()
        min_packages = float('inf')

        for i in range(1, k + 1):
            gcd_value = math.gcd(n, i)
            packages_needed = n // gcd_value
            min_packages = min(min_packages, packages_needed)

        results.append(min_packages)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
